head.b:skin:
/* AI Future Premium — Phase 1: tokens + base + contract */
:root{
  --bg:#F8FAFC; --surface:#FFFFFF; --surface-2:#F1F5F9;
  --ink:#111827; --text:#374151; --muted:#6B7280;
  --border:#E5E7EB; --accent:#FACC15; --accent-ink:#111827;
  --link:#1D4ED8; --danger:#DC2626; --success:#16A34A;
  --grid:#B9C2CF; --bar-bg:#FFFFFF; --bar-fg:#111827; --foot-bg:#F1F5F9;
  --art-heading:#111827; --art-text:#1F2937; --art-muted:#6B7280;
  --art-link:#1D4ED8; --art-ext:#C62828; --art-border:#E5E7EB;
  --radius:16px; --maxw:1180px;
}
html.is-dark{
  --bg:#0D1117; --surface:#151A22; --surface-2:#1B222C;
  --ink:#E6E9EE; --text:#C9D1D9; --muted:#9AA4B2;
  --border:#232A35; --accent:#FACC15; --accent-ink:#111827;
  --link:#8AB6F9; --grid:#39424F; --bar-bg:#151A22; --bar-fg:#E6E9EE; --foot-bg:#0B0F14;
  --art-heading:#FACC15; --art-text:#D3D9E0; --art-muted:#9AA4B2;
  --art-link:#8AB6F9; --art-ext:#FF9E80; --art-border:#232A35;
}
*{box-sizing:border-box}
html{direction:rtl}
html{scroll-behavior:smooth}
body{margin:0;background:var(--bg);color:var(--text);
  font-family:'IBM Plex Sans Arabic',system-ui,Tahoma,sans-serif;
  font-size:18px;line-height:1.9;transition:background-color .25s ease,color .25s ease}
a{color:var(--link)}
img{max-width:100%;height:auto}
.container{max-width:var(--maxw);margin:0 auto;padding:0 16px}
.site-header{background:var(--surface);border-bottom:1px solid var(--border);
  position:sticky;top:0;z-index:50;transition:background-color .25s ease}
.site-header .container{display:flex;align-items:center;justify-content:space-between;padding-top:12px;padding-bottom:12px}
.brand-name{font-size:24px;font-weight:700;color:var(--ink);text-decoration:none}
.brand-desc{display:block;font-size:12.5px;color:var(--muted);line-height:1.5}
.theme-toggle{width:42px;height:42px;border-radius:12px;border:1px solid var(--border);
  background:var(--surface);color:var(--ink);font-size:19px;cursor:pointer;line-height:1}
.theme-toggle:hover{border-color:var(--accent)}
.page-main{display:block;padding:28px 16px 40px}
.post{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);
  padding:26px 28px;margin-bottom:22px;transition:background-color .25s ease}
.post-title{color:var(--ink);font-size:27px;line-height:1.5;margin:0 0 12px;font-weight:700}
.post-title a{color:var(--ink);text-decoration:none}
.site-footer{border-top:2px solid var(--accent);background:var(--foot-bg);
  color:var(--muted);font-size:14px;padding:20px 0;text-align:center}
/* ===== Article contract (variables + base) ===== */
.art-wrap{color:var(--art-text)}
.art-wrap h2,.art-wrap h3{color:var(--art-heading)}
.art-wrap a{color:var(--art-link)}
.art-wrap a.ext-link{color:var(--art-ext)}
.art-wrap a.ext-link::after{content:'\2197';font-size:.82em;margin-inline-start:3px}
.art-wrap mark.kw{background:linear-gradient(transparent 62%,#E9B90C 62%);color:inherit;font-weight:700;padding:0 1px}
html.is-dark .art-wrap mark.kw{background:linear-gradient(transparent 62%,rgba(242,194,48,.5) 62%)}

.home-heading{color:var(--ink);font-size:22px;font-weight:700;margin:0 0 16px}
:root{ --logo-tile:#111827; --logo-spark:#FACC15; --logo-core:#111827; }
html.is-dark{ --logo-tile:#FACC15; --logo-spark:#111827; --logo-core:#FACC15; }
.logo-mark{flex-shrink:0;display:block}
.topbar{background:var(--bar-bg);color:var(--bar-fg);font-size:13.5px;border-bottom:1px solid var(--border)}
.topbar .container{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:6px;padding-bottom:6px;min-height:36px}
.topbar a{color:var(--bar-fg);text-decoration:none;opacity:.85}
.topbar a:hover{opacity:1}
.topbar ul{list-style:none;margin:0;padding:0;display:flex;gap:16px;flex-wrap:wrap}
.topbar .widget>h2,.main-menu .widget>h2{display:none}
#aif-topbar{display:flex;align-items:center;justify-content:space-between;gap:18px;width:100%}
#LinkList1 ul{gap:8px}
a.soc-ic{display:inline-flex;align-items:center;justify-content:center;width:28px;height:28px;border:1px solid var(--border);border-radius:8px;opacity:1}
a.soc-ic:hover{border-color:var(--accent);color:var(--accent)}
.main-menu{border-top:1px solid var(--border);background:var(--surface);position:relative}
.main-menu ul{list-style:none;margin:0;padding:0;display:flex;gap:22px;flex-wrap:wrap;justify-content:center}
.main-menu a{display:block;padding:10px 2px;color:var(--ink);text-decoration:none;font-weight:600;font-size:15.5px}
.main-menu a:hover{color:var(--link)}
.brand{display:flex;align-items:center;gap:12px}
.layout-row{display:flex;gap:28px;align-items:flex-start}
.content-col{flex:1;min-width:0}
.sidebar{width:320px;flex-shrink:0;display:flex;flex-direction:column;gap:20px}
.side-box{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:18px 20px}
.side-box h2,.side-box .title{font-size:17px;color:var(--ink);margin:0 0 10px;font-weight:700}
.side-box ul{list-style:none;margin:0;padding:0}
.side-box li{padding:6px 0;border-bottom:1px dashed var(--border)}
.side-box li:last-child{border-bottom:none}
.band{margin:8px 0 4px}
.footer-grid{display:grid;grid-template-columns:1.3fr 1fr 1fr;gap:28px;text-align:start;padding:8px 0 4px}
.footer-grid h2,.footer-grid .title{font-size:16px;color:var(--ink);margin:0 0 10px;font-weight:700}
.footer-grid h2::before,.footer-grid .title::before{content:'';display:inline-block;width:4px;height:15px;border-radius:2px;background:var(--accent);margin-inline-end:8px;vertical-align:-2px}
#HTML7 a{display:inline-block;padding:5px 12px;margin-inline-end:8px;margin-bottom:8px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);text-decoration:none;font-size:13px}
#HTML7 a:hover{border-color:var(--accent);color:var(--ink)}
.foot-brand{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.foot-brand svg{width:36px;height:36px}
.foot-name{font-weight:700;font-size:18px;color:var(--ink)}
.foot-soc{margin-top:12px}
.foot-soc ul{display:flex;gap:8px;list-style:none;margin:0;padding:0}
.copyright{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:14px;margin-top:16px;text-align:start}
.foot-pages ul{display:flex;gap:16px;list-style:none;margin:0;padding:0;flex-wrap:wrap}
.foot-pages a{color:var(--muted);text-decoration:none}
.foot-pages a:hover{color:var(--ink)}
.footer-grid ul{list-style:none;margin:0;padding:0}
.footer-grid li{padding:3px 0}
.copyright{border-top:1px solid var(--border);margin-top:14px;padding-top:14px;text-align:center}
@media(max-width:900px){ .layout-row{flex-direction:column} .sidebar{width:100%} .footer-grid{grid-template-columns:1fr} }
.rotator{display:none;align-items:center;gap:12px;background:rgba(250,204,21,.16);border:1px solid rgba(250,204,21,.45);border-radius:12px;padding:8px 14px;margin:14px 0 4px;min-height:48px}
.rotator.on{display:flex}
.rotator .dot{width:9px;height:9px;border-radius:50%;background:#3B82F6;flex-shrink:0}
html.is-dark .rotator .dot{background:#FACC15}
.rotator .cat{font-weight:700;color:var(--ink);white-space:nowrap;font-size:14.5px}
.rotator .sep{width:1px;height:20px;background:var(--border);flex-shrink:0}
.rotator .ttl{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--text);font-size:15px;text-decoration:none}
.rotator .nav{display:flex;gap:6px;flex-shrink:0}
.rotator .nav button{width:30px;height:30px;border-radius:50%;border:1px solid var(--border);background:var(--surface);color:var(--ink);cursor:pointer;line-height:1}
.rotator .fade{animation:aifFade .45s ease}
@keyframes aifFade{from{opacity:0}to{opacity:1}}
.featured{display:none;margin:18px 0 6px}
.featured.on{display:block}
.hero-grid{display:grid;grid-template-columns:1.6fr 1fr;gap:16px}
.hero-main{position:relative;border-radius:var(--radius);overflow:hidden;min-height:340px;display:block;text-decoration:none}
.hero-main img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hero-main .ov{position:absolute;inset:0;background:linear-gradient(transparent 40%,rgba(5,8,12,.82))}
.hero-main .tx{position:absolute;bottom:0;padding:20px 22px;color:#fff}
.hero-main .tx h2{margin:0;font-size:24px;line-height:1.5;color:#fff}
.hero-side{display:flex;flex-direction:column;gap:16px}
.hero-card{flex:1;position:relative;border-radius:var(--radius);overflow:hidden;min-height:100px;display:block;text-decoration:none}
.hero-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.hero-card .ov{position:absolute;inset:0;background:linear-gradient(transparent 30%,rgba(5,8,12,.82))}
.hero-card .tx{position:absolute;bottom:0;padding:12px 16px;color:#fff}
.hero-card .tx h3{margin:0;font-size:16.5px;line-height:1.5;color:#fff}
.hero-mini{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:16px}
.mini-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;text-decoration:none;display:block}
.mini-card img{width:100%;height:110px;object-fit:cover;display:block}
.mini-card h3{font-size:15px;line-height:1.6;color:var(--ink);margin:0;padding:10px 12px}
.badge{display:inline-block;background:var(--accent);color:#111827;font-size:12px;font-weight:700;border-radius:999px;padding:2px 10px;margin-bottom:8px}
.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:20px}
.post-card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}
.post-card .thumb{display:block;aspect-ratio:16/9;overflow:hidden;background:var(--surface-2)}
.post-card .thumb img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .3s ease}
.post-card:hover .thumb img{transform:scale(1.04)}
.post-card .cbody{padding:16px 18px}
.post-card .meta{display:flex;gap:10px;align-items:center;font-size:12.5px;color:var(--muted);margin-bottom:6px}
.post-card .cat-badge{background:var(--ink);color:var(--bg);border-radius:999px;padding:1px 9px;font-weight:600}
.post-card h2{font-size:18.5px;line-height:1.6;margin:0 0 6px}
.post-card h2 a{color:var(--ink);text-decoration:none}
.post-card .exc{font-size:14.5px;color:var(--muted);line-height:1.8;margin:0}
@media(max-width:900px){ .hero-grid{grid-template-columns:1fr} .hero-mini{grid-template-columns:repeat(2,1fr)} }
.progress-bar{position:fixed;top:0;right:0;left:0;height:3px;z-index:200;pointer-events:none}
.progress-bar i{display:block;height:100%;background:var(--accent);transform-origin:right;transform:scaleX(0)}
.crumbs{font-size:13.5px;color:var(--muted);margin:0 0 10px}
.crumbs a{color:var(--muted);text-decoration:none}
.crumbs a:hover{color:var(--link)}
.post-meta{display:flex;gap:14px;flex-wrap:wrap;font-size:13.5px;color:var(--muted);margin:0 0 14px}
.share-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:22px 0 6px}
.share-row .lbl{font-weight:700;color:var(--ink);font-size:14.5px}
.share-btn{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--border);background:var(--surface);color:var(--ink);border-radius:999px;padding:6px 14px;font-size:13.5px;font-weight:600;cursor:pointer;text-decoration:none}
.share-btn:hover{border-color:var(--accent)}
.share-btn.ai{border-color:var(--accent);background:rgba(250,204,21,.14)}
.related{margin:26px 0 4px}
.related h2{font-size:20px;color:var(--ink);margin:0 0 14px}
.rel-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px}
.art-wrap p{margin:0 0 14px}
.art-wrap h2{font-size:24px;line-height:1.6;margin:30px 0 12px;padding-inline-start:12px;border-inline-start:4px solid var(--accent)}
.art-wrap h3{font-size:20px;line-height:1.6;margin:24px 0 10px}
.art-wrap ul,.art-wrap ol{margin:0 0 14px;padding-inline-start:24px}
.art-wrap li{margin-bottom:6px}
.art-wrap img{border-radius:12px;border:1px solid var(--art-border)}
.art-wrap figure{margin:18px 0;text-align:center}
.art-wrap figcaption{font-size:13.5px;color:var(--art-muted);margin-top:8px}
.art-wrap .lead-summary{font-size:19px;line-height:1.9;color:var(--art-text);margin:0 0 18px}
.art-wrap .lead-summary strong{color:var(--art-heading)}
.art-wrap .toc-wrapper{border:1px solid var(--art-border);border-radius:14px;padding:16px 20px;margin:0 0 22px}
.art-wrap .toc-head{display:flex;align-items:center;justify-content:space-between;cursor:pointer;font-weight:700;color:var(--art-heading);font-size:17px}
.art-wrap .toc-head .chip{width:26px;height:26px;border-radius:50%;border:1px solid var(--art-border);display:inline-flex;align-items:center;justify-content:center;font-size:15px;flex-shrink:0}
.art-wrap .toc-wrapper ol{counter-reset:toc;margin:12px 0 0;padding:0;list-style:none}
.art-wrap .toc-wrapper li{counter-increment:toc;margin:0}
.art-wrap .toc-wrapper li a{display:flex;gap:10px;align-items:baseline;padding:7px 6px;border-radius:8px;color:var(--art-text);text-decoration:none;font-size:15.5px}
.art-wrap .toc-wrapper li a::before{content:counter(toc);background:var(--surface-2);color:var(--art-heading);border:1px solid var(--art-border);border-radius:8px;min-width:24px;height:24px;display:inline-flex;align-items:center;justify-content:center;font-size:13px;font-weight:700;flex-shrink:0}
.art-wrap .toc-wrapper li a:hover{background:var(--surface-2)}
.art-wrap .toc-wrapper.closed ol{display:none}
.art-wrap h2,.art-wrap h3{scroll-margin-top:100px}
.art-wrap .faq-item{border:1px solid var(--art-border);border-radius:14px;margin:0 0 12px;overflow:hidden}
.art-wrap .faq-question{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;background:none;border:none;cursor:pointer;text-align:start;font:inherit;font-weight:700;color:var(--art-heading);font-size:17px;padding:15px 18px}
.art-wrap .faq-question .chip{width:28px;height:28px;border-radius:50%;border:1.5px solid var(--art-heading);color:var(--art-heading);display:inline-flex;align-items:center;justify-content:center;font-size:17px;flex-shrink:0;line-height:1}
.art-wrap .faq-item.open .faq-question{background:var(--surface-2)}
.art-wrap .faq-item.open .faq-question .chip{background:#E9B90C;border-color:#E9B90C;color:#111827}
.art-wrap .faq-answer{display:none;padding:0 18px 16px;color:var(--art-text)}
.art-wrap .faq-item.open .faq-answer{display:block}
.art-wrap .info-box,.art-wrap .warning-box,.art-wrap .success-box{border:1px solid var(--art-border);border-radius:14px;padding:16px 20px;margin:0 0 18px}
.art-wrap .info-box{border-inline-start:4px solid var(--link)}
.art-wrap .warning-box{border-inline-start:4px solid #E9B90C}
.art-wrap .success-box{border-inline-start:4px solid var(--success)}
.art-wrap blockquote{margin:0 0 18px;padding:6px 20px;border-inline-start:4px solid var(--accent);font-weight:700;font-size:19px;line-height:1.9;color:var(--art-heading)}
.art-wrap blockquote .attribution,.art-wrap blockquote cite{display:block;font-weight:500;font-size:14.5px;color:var(--art-muted);margin-top:8px}
.art-wrap table{width:100%;border-collapse:collapse;margin:0 0 20px;font-size:15.5px}
.art-wrap th,.art-wrap td{border:1px solid var(--grid);padding:10px 12px;text-align:start;vertical-align:top}
.art-wrap th{color:var(--art-heading);font-weight:700;background:transparent}
.art-wrap pre{background:#0D1117;color:#E6E9EE;border-radius:12px;padding:16px 18px;overflow-x:auto;font-size:14px;line-height:1.7;direction:ltr;text-align:left}
.art-wrap code{background:var(--surface-2);border:1px solid var(--art-border);border-radius:6px;padding:1px 7px;font-size:.92em}
.art-wrap pre code{background:none;border:none;padding:0}
.art-wrap .pros-cons{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:0 0 18px}
.art-wrap .pros-cons .col{border:1px solid var(--art-border);border-radius:14px;padding:14px 18px}
.art-wrap .pros-cons ul{list-style:none;padding:0;margin:0}
.art-wrap .pros-cons .pros li::before{content:'\2713';color:var(--success);font-weight:700;margin-inline-end:8px}
.art-wrap .pros-cons .cons li::before{content:'\2717';color:var(--danger);font-weight:700;margin-inline-end:8px}
.art-wrap .guide-box{border:1px dashed var(--art-border);border-radius:14px;padding:16px 20px;margin:0 0 18px}
.art-wrap .art-btn{display:inline-block;background:var(--ink);color:var(--bg);border-radius:999px;padding:10px 22px;font-weight:700;text-decoration:none;font-size:15.5px}
.art-wrap hr{border:none;height:3px;background:var(--accent);border-radius:2px;margin:26px auto;width:120px}
@media(max-width:640px){ .art-wrap table{display:block;overflow-x:auto} .art-wrap .pros-cons{grid-template-columns:1fr} .art-wrap h2{font-size:21px} }
#HTML1 .title,#HTML2 .title{display:none}
.error-page{text-align:center;padding:30px 10px 10px}
.aif-empty-check{display:none}
.aif-empty-check.show{display:block}
.error-code{font-size:84px;font-weight:700;color:var(--accent);line-height:1}
.error-search{display:flex;gap:8px;justify-content:center;margin:18px 0;flex-wrap:wrap}
.error-search input{border:1px solid var(--border);background:var(--surface);color:var(--ink);border-radius:999px;padding:10px 18px;font:inherit;font-size:15px;min-width:240px}
.error-search button{background:var(--ink);color:var(--bg);border:none;border-radius:999px;padding:10px 22px;font:inherit;font-weight:700;cursor:pointer}
.hdr-actions{display:flex;gap:8px;align-items:center;margin-inline-start:auto}
.aif-header-sec{display:none}
.topbar .container,.site-header .container,.main-menu .container{max-width:none;padding-inline:22px}
@media(max-width:640px){.topbar .container,.site-header .container,.main-menu .container{padding-inline:14px}}
.icon-btn,.theme-toggle{transition:border-color .2s ease,color .2s ease,background-color .2s ease}
#aifThemeToggle{order:3}
#aifSearchBtn{order:2}
#aifBurger{order:1}
.icon-btn svg,.theme-toggle svg{display:block}
.theme-toggle{display:inline-flex;align-items:center;justify-content:center}
.theme-toggle .ic-sun{display:none}
html.is-dark .theme-toggle .ic-sun{display:block}
html.is-dark .theme-toggle .ic-moon{display:none}
#HTML21>h2,#HTML22>h2,#HTML23>h2,#HTML24>h2,#HTML4>h2{display:none}
.icon-btn{width:42px;height:42px;border-radius:12px;border:1px solid var(--border);background:var(--surface);color:var(--ink);font-size:18px;cursor:pointer;line-height:1;display:inline-flex;align-items:center;justify-content:center}
.icon-btn:hover{border-color:var(--accent)}
.burger{display:none}
.search-overlay{position:fixed;top:0;right:0;left:0;z-index:300;background:var(--surface);border-bottom:1px solid var(--border);padding:26px 16px 30px;transform:translateY(-105%);transition:transform .28s ease;box-shadow:0 20px 50px rgba(0,0,0,.12)}
.search-overlay.open{transform:none}
.search-overlay form{display:flex;gap:10px;max-width:720px;margin:0 auto}
.search-overlay input{flex:1;border:1.5px solid var(--border);background:var(--bg);color:var(--ink);border-radius:999px;padding:13px 22px;font:inherit;font-size:17px}
.search-overlay input:focus{outline:none;border-color:var(--accent)}
.search-overlay .go{background:var(--ink);color:var(--bg);border:none;border-radius:999px;padding:13px 26px;font:inherit;font-weight:700;cursor:pointer}
.search-overlay .x{position:absolute;top:14px;inset-inline-end:16px;background:none;border:none;color:var(--muted);font-size:22px;cursor:pointer}
.search-overlay .x:hover{color:var(--danger)}
.scrim{position:fixed;inset:0;background:rgba(5,8,12,.45);opacity:0;pointer-events:none;transition:opacity .25s ease;z-index:290}
.scrim.on{opacity:1;pointer-events:auto}
.drawer{position:fixed;top:0;bottom:0;right:0;width:300px;max-width:85vw;background:var(--surface);z-index:310;transform:translateX(106%);transition:transform .28s ease;padding:20px;overflow-y:auto;box-shadow:-16px 0 40px rgba(0,0,0,.14)}
.drawer.open{transform:none}
.drawer .d-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.drawer .d-title{font-weight:700;color:var(--ink);font-size:18px}
.drawer .x{background:none;border:1px solid var(--border);border-radius:50%;width:34px;height:34px;color:var(--ink);cursor:pointer;font-size:16px}
.drawer ul{list-style:none;margin:0 0 18px;padding:0}
.drawer li a{display:block;padding:10px 6px;color:var(--ink);text-decoration:none;font-weight:600;border-bottom:1px dashed var(--border)}
.drawer .d-sec{font-size:13px;color:var(--muted);font-weight:700;margin:14px 0 4px}
.mega{position:absolute;top:100%;right:0;left:0;background:var(--surface);border:1px solid var(--border);border-radius:0 0 16px 16px;padding:18px 20px;display:none;z-index:60;box-shadow:0 18px 40px rgba(0,0,0,.10)}
.mega.on{display:block}
.mega .m-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.mega .m-head strong{color:var(--ink);font-size:16.5px}
.mega .m-head a{font-size:13.5px;font-weight:700}
.to-top{position:fixed;bottom:22px;inset-inline-end:22px;width:46px;height:46px;border-radius:12px;border:1px solid var(--border);background:var(--surface);color:var(--ink);font-size:19px;cursor:pointer;opacity:0;pointer-events:none;transition:opacity .25s ease;z-index:150;box-shadow:0 8px 24px rgba(0,0,0,.10)}
.to-top.on{opacity:1;pointer-events:auto}
#PopularPosts1 ul{counter-reset:pop}
#PopularPosts1 li{counter-increment:pop;position:relative;padding-inline-start:44px;min-height:36px}
#PopularPosts1 li::before{content:counter(pop,decimal-leading-zero);position:absolute;inset-inline-start:0;top:4px;font-weight:700;font-size:19px;color:#E9B90C}
#HTML21,#HTML22,#HTML23{text-align:center;margin:14px 0}
#HTML22{display:none}
#HTML24{position:absolute;visibility:hidden;height:0;overflow:hidden;margin:0;padding:0}
.inart-ad{text-align:center;margin:20px 0}
.comments{margin:28px 0 6px}
.comments h4{font-size:20px;color:var(--ink);margin:0 0 16px}
.comment-item{border:1px solid var(--border);border-radius:14px;padding:14px 18px;margin:0 0 12px;background:var(--surface)}
.comment-head{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:4px}
.comment-author{font-weight:700;color:var(--ink)}
.comment-author a{color:var(--ink);text-decoration:none}
.comment-time{font-size:12.5px;color:var(--muted)}
.comment-time a{color:var(--muted);text-decoration:none}
.comment-form{border:1px solid var(--border);border-radius:14px;padding:18px 20px;margin-top:18px;background:var(--surface)}
.comment-form h4{margin:0 0 10px;font-size:17px;color:var(--ink)}
.comment-form iframe{width:100%;border:0;min-height:410px}
.delete-comment-icon a{color:#DC2626;font-size:12.5px}
.author-box{display:flex;gap:16px;align-items:flex-start;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:20px 22px;margin:24px 0 6px}
.author-box .av{width:64px;height:64px;border-radius:50%;background:var(--surface-2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;flex-shrink:0}
.author-box h3{margin:0 0 4px;font-size:17px;color:var(--ink)}
.author-box p{margin:0;font-size:14.5px;color:var(--muted);line-height:1.8}
.author-box{display:flex;gap:16px;align-items:flex-start;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface-2);padding:20px 22px;margin:26px 0 6px}
.author-box .av{flex-shrink:0;width:64px;height:64px;border-radius:50%;background:var(--surface);border:1px solid var(--border);display:flex;align-items:center;justify-content:center}
.author-box h3{margin:0 0 4px;font-size:17.5px;color:var(--ink)}
.author-box p{margin:0;font-size:14.5px;color:var(--muted);line-height:1.8}
@media(max-width:900px){ .main-menu{display:none} .burger{display:inline-flex} }

body.script:
//
(function(){
  function imgOf(e){ try{ var m=e.media$thumbnail; if(m&&m.url){ return m.url.replace(/\/s72-c\//,'/s800/').replace(/\/s72\//,'/s800/'); } }catch(x){} return ''; }
  function catOf(e){ return (e.category&&e.category.length)? e.category[0].term : ''; }
  function linkOf(e){ for(var i=0;i<e.link.length;i++){ if(e.link[i].rel==='alternate') return e.link[i].href; } return '#'; }
  function esc(s){ var d=document.createElement('div'); d.textContent=s||''; return d.innerHTML; }
  function entries(j){ return (j&&j.feed&&j.feed.entry)? j.feed.entry : []; }
  function get(url,cb){ var x=new XMLHttpRequest(); x.open('GET',url,true); x.onreadystatechange=function(){ if(x.readyState===4&&x.status===200){ try{ cb(JSON.parse(x.responseText)); }catch(e){} } }; x.send(); }
  var base = location.origin + '/';
  // Rotator: latest 6
  var rot=document.getElementById('aifRotator');
  if(rot){
    get(base+'feeds/posts/default?alt=json&max-results=6&orderby=published', function(j){
      var es=entries(j); if(!es.length) return;
      var i=0,timer=null;
      rot.innerHTML='<span class="dot"></span><span class="cat"></span><span class="sep"></span><a class="ttl" href="#"></a><span class="nav"><button aria-label="السابق" id="rotPrev" type="button">&#8250;</button><button aria-label="التالي" id="rotNext" type="button">&#8249;</button></span>';
      var cat=rot.querySelector('.cat'), ttl=rot.querySelector('.ttl');
      function show(n){ i=(n+es.length)%es.length; var e=es[i];
        ttl.classList.remove('fade'); void ttl.offsetWidth; ttl.classList.add('fade');
        cat.textContent=catOf(e); ttl.textContent=e.title.$t; ttl.href=linkOf(e); }
      function auto(){ timer=setInterval(function(){ show(i+1); },5500); }
      document.getElementById('rotNext').addEventListener('click',function(){ show(i+1); });
      document.getElementById('rotPrev').addEventListener('click',function(){ show(i-1); });
      rot.addEventListener('mouseenter',function(){ if(timer) clearInterval(timer); });
      rot.addEventListener('mouseleave',auto);
      rot.classList.add('on'); show(0); auto();
    });
  }
  // Featured: label Mميز first, fallback latest — 7 posts hero
  var feat=document.getElementById('aifFeatured');
  if(feat && location.pathname==='/'){
    function render(es){
      if(!es.length) return;
      function card(e,cls,tag){ var im=imgOf(e); return '<a class="'+cls+'" href="'+linkOf(e)+'">'+(im? '<img alt="" src="'+im+'"/>':'')+'<span class="ov"></span><span class="tx"><span class="badge">'+esc(catOf(e))+'</span><'+tag+'>'+esc(e.title.$t)+'</'+tag+'></span></a>'; }
      var h='<div class="hero-grid">'+card(es[0],'hero-main','h2')+'<div class="hero-side">';
      if(es[1]) h+=card(es[1],'hero-card','h3');
      if(es[2]) h+=card(es[2],'hero-card','h3');
      h+='</div></div>';
      if(es.length>3){ h+='<div class="hero-mini">'; for(var k=3;k<Math.min(7,es.length);k++){ var e=es[k],im=imgOf(e); h+='<a class="mini-card" href="'+linkOf(e)+'">'+(im? '<img alt="" src="'+im+'"/>':'')+'<h3>'+esc(e.title.$t)+'</h3></a>'; } h+='</div>'; }
      feat.innerHTML=h; feat.classList.add('on');
    }
    get(base+'feeds/posts/default/-/'+encodeURIComponent('مميز')+'?alt=json&max-results=7&orderby=published', function(j){
      var es=entries(j);
      if(es.length){ render(es); }
      else { get(base+'feeds/posts/default?alt=json&max-results=7&orderby=published', function(j2){ render(entries(j2)); }); }
    });
  }
})();
//

//
(function(){
  var bar=document.getElementById('aifProgress');
  if(bar){ var tick=false;
    function upd(){ var h=document.documentElement; var max=h.scrollHeight-h.clientHeight; var p=max>0? (h.scrollTop/max):0; bar.style.transform='scaleX('+p+')'; tick=false; }
    addEventListener('scroll',function(){ if(!tick){ tick=true; requestAnimationFrame(upd); } },{passive:true}); upd();
  }
  var ew=document.getElementById('HTML22');
  if(ew && /\/\d{4}\/\d{2}\/[^/]+\.html/.test(location.pathname)) ew.style.display='block';
  var src=document.getElementById('HTML24');
  var abody=document.querySelector('.post-body');
  if(src && abody && /\/\d{4}\/\d{2}\/[^/]+\.html/.test(location.pathname) && !abody.querySelector('.aif-no-ads')){
    var wc=src.querySelector('.widget-content');
    if(wc && wc.innerHTML.trim().length>0){
      var ps=abody.querySelectorAll('.art-wrap > p, .post-body > p');
      if(ps.length>=6){ var mid=ps[Math.floor(ps.length*0.45)];
        var ad=document.createElement('div'); ad.className='inart-ad'; ad.innerHTML=wc.innerHTML;
        mid.parentNode.insertBefore(ad, mid.nextSibling); }
    }
  }
  var sb=document.querySelector('.aif-empty-check');
  if(sb && !document.querySelector('.post-card')) sb.classList.add('show');
  document.querySelectorAll('[data-share]').forEach(function(b){
    b.addEventListener('click',function(){
      var u=encodeURIComponent(location.href), t=encodeURIComponent(document.title), k=b.getAttribute('data-share'), url='';
      if(k==='x') url='https://twitter.com/intent/tweet?url='+u+'&text='+t;
      if(k==='fb') url='https://www.facebook.com/sharer/sharer.php?u='+u;
      if(k==='wa') url='https://wa.me/?text='+t+'%20'+u;
      if(k==='tg') url='https://t.me/share/url?url='+u+'&text='+t;
      if(k==='ai') url='https://chatgpt.com/?q='+encodeURIComponent('اشرح لي هذا المقال وأجب عن أسئلتي حوله: '+location.href);
      if(k==='copy'){ if(navigator.clipboard){ navigator.clipboard.writeText(location.href); } b.textContent='تم النسخ ✓'; setTimeout(function(){ b.textContent='نسخ الرابط'; },1800); return; }
      if(url) window.open(url,'_blank','width=640,height=560');
    });
  });
  // TOC collapse + FAQ accordion enhancers (unified article CSS contract)
  document.querySelectorAll('.art-wrap .toc-wrapper, .post-body .toc-wrapper').forEach(function(tw){
    var head=tw.querySelector('.toc-title,.toc-head,h3,h4,strong');
    if(!head) return;
    var wrap=document.createElement('div'); wrap.className='toc-head';
    head.parentNode.insertBefore(wrap,head); wrap.appendChild(head);
    var chip=document.createElement('span'); chip.className='chip'; chip.textContent='\u2212'; wrap.appendChild(chip);
    wrap.addEventListener('click',function(){ var c=tw.classList.toggle('closed'); chip.textContent=c? '+':'\u2212'; });
  });
  document.querySelectorAll('.faq-item').forEach(function(it){
    var q=it.querySelector('.faq-question'); if(!q) return;
    var ch=q.querySelector('.chip');
    if(!ch){ var spans=q.querySelectorAll('span'); for(var i=0;i<spans.length;i++){ var tx=spans[i].textContent.trim(); if(tx==='+'||tx==='\u2212'||tx==='-'){ ch=spans[i]; ch.classList.add('chip'); break; } } }
    if(!ch){ ch=document.createElement('span'); ch.className='chip'; ch.textContent='+'; q.appendChild(ch); }
    q.addEventListener('click',function(){ var o=it.classList.toggle('open'); if(ch) ch.textContent=o? '\u2212':'+'; });
  });
  // Related posts by first label
  var rel=document.getElementById('aifRelated');
  if(rel && window.AIF_LABELS && AIF_LABELS.length){
    var lab=AIF_LABELS[0];
    var base=location.origin+'/';
    var x=new XMLHttpRequest();
    x.open('GET', base+'feeds/posts/default/-/'+encodeURIComponent(lab)+'?alt=json&max-results=5&orderby=published', true);
    function paint(es){ var out='';
      es.forEach(function(e){ var href='#'; for(var i=0;i<e.link.length;i++){ if(e.link[i].rel==='alternate') href=e.link[i].href; }
        if(href===location.href) return;
        var im=''; try{ if(e.media$thumbnail) im=e.media$thumbnail.url.replace(/\/s72-c\//,'/s400/').replace(/\/s72\//,'/s400/'); }catch(z){}
        out+='<a class="mini-card" href="'+href+'">'+(im? '<img alt="" src="'+im+'"/>':'')+'<h3>'+e.title.$t+'</h3></a>'; });
      if(out) rel.innerHTML='<h2>مقالات ذات صلة</h2><div class="rel-grid">'+out+'</div>';
      return out; }
    x.onreadystatechange=function(){ if(x.readyState===4&&x.status===200){ try{
      var j=JSON.parse(x.responseText), es=(j.feed&&j.feed.entry)||[];
      if(!paint(es)){ var x2=new XMLHttpRequest(); x2.open('GET', base+'feeds/posts/default?alt=json&max-results=5&orderby=published', true);
        x2.onreadystatechange=function(){ if(x2.readyState===4&&x2.status===200){ try{ var j2=JSON.parse(x2.responseText); paint((j2.feed&&j2.feed.entry)||[]); }catch(e){} } }; x2.send(); }
    }catch(e){} } };
    x.send();
  }
})();
//

//
(function(){
  var scrim=document.getElementById('aifScrim');
  var drawer=document.getElementById('aifDrawer');
  var search=document.getElementById('aifSearch');
  function closeAll(){ if(drawer) drawer.classList.remove('open'); if(search) search.classList.remove('open'); if(scrim) scrim.classList.remove('on'); }
  function fillNav(srcSel,dstId){ var src=document.querySelector(srcSel), dst=document.getElementById(dstId); if(src&&dst){ var ul=src.querySelector('ul'); if(ul) dst.innerHTML='<ul>'+ul.innerHTML+'</ul>'; } }
  fillNav('.main-menu','aifDrawerMenu');
  fillNav('.topbar','aifDrawerPages');
  var burger=document.getElementById('aifBurger');
  if(burger) burger.addEventListener('click',function(){ closeAll(); drawer.classList.add('open'); scrim.classList.add('on'); });
  var dx=document.getElementById('aifDrawerX'); if(dx) dx.addEventListener('click',closeAll);
  var sb=document.getElementById('aifSearchBtn');
  if(sb) sb.addEventListener('click',function(){ closeAll(); search.classList.add('open'); var i=search.querySelector('input'); if(i) i.focus(); });
  var sx=document.getElementById('aifSearchX'); if(sx) sx.addEventListener('click',closeAll);
  if(scrim) scrim.addEventListener('click',closeAll);
  document.addEventListener('keydown',function(e){ if(e.key==='Escape') closeAll(); });
  var top=document.getElementById('aifTop');
  if(top){ addEventListener('scroll',function(){ top.classList.toggle('on', scrollY>600); },{passive:true});
    top.addEventListener('click',function(){ scrollTo({top:0,behavior:'smooth'}); }); }
  var mega=document.getElementById('aifMega');
  if(mega && matchMedia('(hover:hover) and (min-width:901px)').matches){
    var base=location.origin+'/', cache={}, cur=null, intent=null;
    function imgOf(e){ try{ var m=e.media$thumbnail; if(m&&m.url){ return m.url.replace(/\/s72-c\//,'/s400/').replace(/\/s72\//,'/s400/'); } }catch(x){} return ''; }
    function linkOf(e){ for(var i=0;i<e.link.length;i++){ if(e.link[i].rel==='alternate') return e.link[i].href; } return '#'; }
    function esc(t){ var d=document.createElement('div'); d.textContent=t||''; return d.innerHTML; }
    function render(name,href,es){ var out='<div class="m-head"><strong>'+esc(name)+'</strong><a href="'+href+'">عرض كل المقالات &#8592;</a></div><div class="rel-grid">';
      es.forEach(function(e){ var im=imgOf(e); out+='<a class="mini-card" href="'+linkOf(e)+'">'+(im? '<img alt="" src="'+im+'"/>':'')+'<h3>'+esc(e.title.$t)+'</h3></a>'; });
      mega.innerHTML=out+'</div>'; mega.classList.add('on'); }
    document.querySelectorAll('.main-menu ul li a').forEach(function(a){
      var m=a.getAttribute('href').match(/\/search\/label\/([^?#]+)/); if(!m) return;
      var name=decodeURIComponent(m[1]);
      a.addEventListener('mouseenter',function(){ cur=name; intent=setTimeout(function(){
        if(cache[name]){ render(name,a.href,cache[name]); return; }
        var x=new XMLHttpRequest(); x.open('GET', base+'feeds/posts/default/-/'+encodeURIComponent(name)+'?alt=json&max-results=5&orderby=published', true);
        x.onreadystatechange=function(){ if(x.readyState===4&&x.status===200){ try{ var j=JSON.parse(x.responseText), es=(j.feed&&j.feed.entry)||[]; cache[name]=es; if(cur===name&&es.length) render(name,a.href,es); }catch(e){} } }; x.send();
      },150); });
      a.addEventListener('mouseleave',function(){ if(intent) clearTimeout(intent); cur=null; setTimeout(function(){ if(!mega.matches(':hover')) mega.classList.remove('on'); },250); });
    });
    mega.addEventListener('mouseleave',function(){ mega.classList.remove('on'); });
  }
})();
//
